def preset_settings(name):
    category = PRESETS[name]['category']
    family, genre, voice, register, timbres, instruments, bpm, notes = PRESETS[name]['profile']
    if genre == 'Melodic rap': genre = 'Pop rap'
    if genre not in GENRE_GROUPS[family]:
        family = next(group for group, genres in GENRE_GROUPS.items() if genre in genres)
    settings = {'genre_family':family, f'genre_{family}':genre, f'region_{family}':'Auto / жанрға сай',
        'voice_type':voice, 'voice_timbres':timbres, 'voice_details':'', 'mood':'Uplifting',
        'delivery':[], 'backing':MIX_OPTIONS['Бэк-вокал'][2], 'autotune':AUTOTUNE[2],
        'blend':[], 'instruments':instruments, 'auto_tempo':False, 'tempo':bpm,
        'meter':'4/4 straight', 'structure':STRUCTURES[1], 'dynamics':MIX_OPTIONS['Динамика'][2],
        'production':PRODUCTION[1], 'reverb':REVERB[4], 'delay':DELAY[1],
        'compression':MIX_OPTIONS['Компрессия'][2], 'eq':MIX_OPTIONS['EQ / тон'][4],
        'saturation':MIX_OPTIONS['Сатурация'][2], 'stereo':MIX_OPTIONS['Стерео'][2],
        'placement':MIX_OPTIONS['Вокалдың микстегі орны'][1], 'custom_notes':notes,
        'avoid':'Нақты орындаушының дауысын, белгілі әннің әуенін, мәтінін және ерекше ілмегін көшірмеу.'}
    if register: settings[f'voice_range_{voice}'] = register
    if category == 'атмосфералық трэп':
        settings.update(mood='Dark', autotune=AUTOTUNE[5], reverb=REVERB[10], delay=DELAY[7],
                        delivery=['Melodic rap'], meter='Half-time')
    elif 'рэп' in category or category == 'хип-хоп':
        settings.update(mood='Energetic', delivery=['Fast rap flow'], reverb=REVERB[2])
    elif category.startswith('опера') or category == 'қазақ дәстүрі':
        settings.update(autotune=AUTOTUNE[1], delivery=['Legato / flowing phrases','Gentle vibrato'], reverb=REVERB[5])
    settings.update(OVERRIDES.get(name, {}))
    return settings
